const body = $input.first().json.body ?? $input.first().json;
const action = (body.action ?? '').trim();
const validActions = ['get_slots', 'book', 'update', 'delete'];
if (!validActions.includes(action)) {
  return [{ json: { valid: false, error: `action inválido: ${action}. Válidos: ${validActions.join(', ')}` } }];
}
// Validate per action
if (action === 'get_slots' && (!body.client_id || !body.branch_id || !body.date)) {
  return [{ json: { valid: false, error: 'get_slots requiere client_id, branch_id, date' } }];
}
if (action === 'book' && (!body.client_id || !body.branch_id || !body.date || !body.time)) {
  return [{ json: { valid: false, error: 'book requiere client_id, branch_id, date, time' } }];
}
if ((action === 'update' || action === 'delete') && (!body.calendar_id || !body.event_id)) {
  return [{ json: { valid: false, error: `${action} requiere calendar_id, event_id` } }];
}
return [{ json: { valid: true, action, ...body } }];

const input = $('Validate Input').first().json;
const rows = $input.all().map(r => r.json);

if (!rows || rows.length === 0) {
  return [{ json: { no_calendar: true, available_slots: [] } }];
}

const branch = rows[0];

const date = new Date(input.date + 'T12:00:00');
const dayAbbrs = ['DO', 'LU', 'MA', 'MI', 'JU', 'VI', 'SA'];
const dayAbbr = dayAbbrs[date.getDay()];

const serviceDays = (branch.service_days || '').split(/[-,]/);
if (!serviceDays.includes(dayAbbr)) {
  return [{ json: { no_calendar: true, available_slots: [], reason: 'not_service_day' } }];
}

const [openH, openM] = (branch.open_time || '08:00').split(':').map(Number);
const [closeH, closeM] = (branch.close_time || '18:00').split(':').map(Number);

// 🔥 Helper para formato ISO con -03:00
function toArgentinaISO(dateStr, hours, minutes) {
  const d = new Date(dateStr);
  d.setHours(hours, minutes, 0, 0);

  const yyyy = d.getFullYear();
  const mm = String(d.getMonth() + 1).padStart(2, '0');
  const dd = String(d.getDate()).padStart(2, '0');
  const hh = String(d.getHours()).padStart(2, '0');
  const min = String(d.getMinutes()).padStart(2, '0');
  const ss = '00';

  return `${yyyy}-${mm}-${dd}T${hh}:${min}:${ss}-03:00`;
}

// Build items
return rows.map(r => ({
  json: {
    calendar_id: r.calendar_id,
    workshop_id: r.workshop_id,
    branch: branch,
    input: input,
    start_iso: toArgentinaISO(input.date, openH, openM),
    end_iso: toArgentinaISO(input.date, closeH, closeM)
  }
}));

// Get all tagged busy events (each has calendar_id injected by 'Tag Events with Workshop')
const allResults = $input.all().map(r => r.json);

// Get workshop info from prepare node
const workshopItems = $('Prepare Availability Check').all().map(r => r.json);

if (!workshopItems.length) {
  return [{ json: { success: true, available_slots: [] } }];
}

if (workshopItems[0].no_calendar) {
  return [{ json: { success: true, available_slots: [], reason: workshopItems[0].reason } }];
}

const input = workshopItems[0].input;
const branch = workshopItems[0].branch;
const dateStr = input.date;
const durationMs = (input.duration_minutes || 60) * 60000;
const slotIntervalMs = 30 * 60000;
const totalSlots = 6;
// Distribute slots evenly: 1 workshop=6, 2 workshops=3 each, 3 workshops=2 each, etc.
const slotsPerWorkshop = Math.ceil(totalSlots / workshopItems.length);

// Build busy map per calendar using the calendar_id tagged by the previous node
const busyByCalendar = {};
workshopItems.forEach(w => {
  if (w.calendar_id) busyByCalendar[w.calendar_id] = [];
});

allResults.forEach(result => {
  const calId = result.calendar_id;
  if (!calId || !(calId in busyByCalendar)) return;
  const startStr = result.start?.dateTime ?? result.start ?? '';
  const endStr   = result.end?.dateTime   ?? result.end   ?? '';
  const start = new Date(startStr);
  const end   = new Date(endStr);
  if (!isNaN(start) && !isNaN(end)) {
    busyByCalendar[calId].push({ start, end });
  }
});

const [openH, openM] = (branch.open_time || '08:00').split(':').map(Number);
const [closeH, closeM] = (branch.close_time || '18:00').split(':').map(Number);

let current = new Date(`${dateStr}T${String(openH).padStart(2,'0')}:${String(openM).padStart(2,'0')}:00-03:00`);
const dayEnd = new Date(`${dateStr}T${String(closeH).padStart(2,'0')}:${String(closeM).padStart(2,'0')}:00-03:00`);
const now = new Date();

// Lunch
let lunchStart = null, lunchEnd = null;
if (branch.lunch_start_time && branch.lunch_duration) {
  const [lh, lm] = branch.lunch_start_time.split(':').map(Number);
  lunchStart = new Date(`${dateStr}T${String(lh).padStart(2,'0')}:${String(lm).padStart(2,'0')}:00-03:00`);
  lunchEnd = new Date(lunchStart.getTime() + branch.lunch_duration * 60000);
}

// Breaks
const breaks = [];
for (const n of [1, 2, 3]) {
  const bt = branch[`break${n}_time`], bd = branch[`break${n}_duration`];
  if (bt && bd) {
    const [bh, bm] = bt.split(':').map(Number);
    const bs = new Date(`${dateStr}T${String(bh).padStart(2,'0')}:${String(bm).padStart(2,'0')}:00-03:00`);
    breaks.push({ start: bs, end: new Date(bs.getTime() + bd * 60000) });
  }
}

// Time filters
let afterTime = null, beforeTime = null;
if (input.after_time) {
  const [ah, am] = input.after_time.split(':').map(Number);
  afterTime = new Date(`${dateStr}T${String(ah).padStart(2,'0')}:${String(am).padStart(2,'0')}:00-03:00`);
}
if (input.before_time) {
  const [bh, bm] = input.before_time.split(':').map(Number);
  beforeTime = new Date(`${dateStr}T${String(bh).padStart(2,'0')}:${String(bm).padStart(2,'0')}:00-03:00`);
}

const availableSlots = [];
// Track how many slots each workshop has contributed
const slotCountByWorkshop = {};
workshopItems.forEach(w => { slotCountByWorkshop[w.workshop_id] = 0; });

while (current.getTime() + durationMs <= dayEnd.getTime()) {
  const slotEnd = new Date(current.getTime() + durationMs);

  if (current <= now) {
    current = new Date(current.getTime() + slotIntervalMs);
    continue;
  }
  if (afterTime && current < afterTime) {
    current = new Date(current.getTime() + slotIntervalMs);
    continue;
  }
  if (beforeTime && current >= beforeTime) break;

  if (lunchStart && current < lunchEnd && slotEnd > lunchStart) {
    current = new Date(current.getTime() + slotIntervalMs);
    continue;
  }

  let overlapsBreak = false;
  for (const br of breaks) {
    if (current < br.end && slotEnd > br.start) { overlapsBreak = true; break; }
  }
  if (overlapsBreak) {
    current = new Date(current.getTime() + slotIntervalMs);
    continue;
  }

  // Find first free workshop that hasn't reached its per-workshop quota
  let freeWorkshop = null;
  for (const w of workshopItems) {
    if (slotCountByWorkshop[w.workshop_id] >= slotsPerWorkshop) continue;
    const busy = busyByCalendar[w.calendar_id] || [];
    if (!busy.some(b => current < b.end && slotEnd > b.start)) {
      freeWorkshop = w;
      break;
    }
  }

  if (freeWorkshop) {
    const localH = ((current.getUTCHours() - 3) + 24) % 24;
    const localM = current.getUTCMinutes();
    availableSlots.push({
      time: `${String(localH).padStart(2,'0')}:${String(localM).padStart(2,'0')}`,
      workshop_id: freeWorkshop.workshop_id,
      calendar_id: freeWorkshop.calendar_id
    });
    slotCountByWorkshop[freeWorkshop.workshop_id]++;
  }

  if (availableSlots.length >= totalSlots) break;

  current = new Date(current.getTime() + slotIntervalMs);
}

return [{ json: { success: true, date: dateStr, available_slots: availableSlots } }];

const input = $('Validate Input').first().json;
const rows = $input.all().map(r => r.json);

if (!rows || rows.length === 0) {
  return [{ json: { no_calendar: true } }];
}

const branch = rows[0];

// Map JS getDay() (0=Sun,1=Mon,...6=Sat) to Argentine abbreviations
const date = new Date(input.date + 'T12:00:00');
const dayAbbrs = ['DO', 'LU', 'MA', 'MI', 'JU', 'VI', 'SA'];
const dayAbbr = dayAbbrs[date.getDay()];
// service_days format: "MA-MI-JU-VI-DO" (hyphens) or "LU,MA,MI" (commas)
const serviceDays = (branch.service_days || '').split(/[-,]/);
if (!serviceDays.includes(dayAbbr)) {
  return [{ json: { no_calendar: true, available_slots: [], reason: 'not_service_day' } }];
}

const [h, m] = input.time.split(':').map(Number);
const slotStart = `${input.date}T${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}:00`;
const endMs = new Date(slotStart + '-03:00').getTime() + (input.duration_minutes || 60) * 60000 + 600000; // +10min buffer
const slotEnd = new Date(endMs).toISOString().slice(0,19);

return rows.map(r => ({
  json: {
    calendar_id: r.calendar_id,
    workshop_id: r.workshop_id,
    input: input,
    time_min: slotStart,
    time_max: slotEnd
  }
}));

const allBusySlots = $input.all().map(r => r.json);
const workshopItems = $('Prepare Book Check').all().map(r => r.json);

if (!workshopItems.length || workshopItems[0]?.no_calendar) {
  return [{ json: { found: false } }];
}

const input = workshopItems[0].input;
const [h, m] = input.time.split(':').map(Number);
const tzOffset = '-03:00';
const slotStart = new Date(`${input.date}T${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}:00${tzOffset}`);
const slotEnd = new Date(slotStart.getTime() + (input.duration_minutes || 60) * 60000);

// For each workshop, check if it has any conflicting busy period.
// n8n returns all busy periods from all workshops merged together.
// With multiple workshops we'd need to track by calendar_id.
// For now: if any single busy period overlaps the requested slot, the workshop is considered busy.
// We try each workshop independently assuming all busy slots come from all workshops combined.
let freeWorkshop = null;

for (const w of workshopItems) {
  // Check if this workshop has a conflict in the busy slots
  const hasConflict = allBusySlots.some(b => {
    const busyStart = new Date(b.start?.dateTime || b.start || b.startTime || '');
    const busyEnd = new Date(b.end?.dateTime || b.end || b.endTime || '');
    if (isNaN(busyStart) || isNaN(busyEnd)) return false;
    return slotStart < busyEnd && slotEnd > busyStart;
  });

  if (!hasConflict) {
    freeWorkshop = w;
    break;
  }
}

if (!freeWorkshop) {
  return [{ json: { found: false } }];
}

return [{ json: {
  found: true,
  calendar_id: freeWorkshop.calendar_id,
  workshop_id: freeWorkshop.workshop_id,
  input: input,
  start_iso: slotStart.toISOString(),
  end_iso: slotEnd.toISOString()
}}];

const workshopData = $('Find Free Workshop').first().json;
const createdEvent = $input.first().json;
return [{ json: {
  success: true,
  event_id: createdEvent.id || createdEvent.eventId || '',
  workshop_id: workshopData.workshop_id,
  calendar_id: workshopData.calendar_id
}}];

const workshopItem = $('Prepare Availability Check').item.json;
return {
  json: {
    ...($json),
    calendar_id: workshopItem.calendar_id,
    workshop_id: workshopItem.workshop_id
  }
};
